+            Map<String, Integer> headers = parser.getHeaderMap();
+            Set<String> missingHeaders = REQUIRED_HEADERS.stream()
+                .filter(header -> !headers.containsKey(header))
+                .collect(Collectors.toCollection(java.util.TreeSet::new));
